CREATE INDEX lightning_pool_session_by_cash_session ON public.lightning_pool_session USING btree (cash_player_session_id);
CREATE INDEX lightning_pool_session_by_epoch ON public.lightning_pool_session USING btree (cluster_id, cluster_epoch);
CREATE UNIQUE INDEX lightning_pool_session_one_open ON public.lightning_pool_session USING btree (player_id, cluster_id) WHERE (exited_at IS NULL);
CREATE UNIQUE INDEX lightning_pool_session_one_open_per_anchor ON public.lightning_pool_session USING btree (anchor_seat_id) WHERE (exited_at IS NULL);
CREATE INDEX lightning_pool_session_open_by_cluster ON public.lightning_pool_session USING btree (cluster_id, cluster_epoch) WHERE (exited_at IS NULL);
CREATE OR REPLACE FUNCTION public.fn_lightning_refuses_truncate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- A STATEMENT-LEVEL BEFORE TRUNCATE trigger, because row triggers do not
  -- fire on TRUNCATE and every immutability rule in Phase 9 is a row trigger.
  -- It fires for every role, the owner included, and for a TRUNCATE that
  -- arrives by CASCADE. History is closed, not deleted.
  RAISE EXCEPTION 'LIGHTNING_HISTORY_IS_NOT_TRUNCATABLE: TRUNCATE of %.% was refused; row triggers do not fire on TRUNCATE, so it would erase in one statement every hand, participant, instance, reservation, slot, pool session or blind ledger row the row triggers exist to keep',
    TG_TABLE_SCHEMA, TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';
END
$function$;
